(()=>{async function n(n,t){const i=t.textContent;t.disabled=!0;t.innerHTML='<span class="spinner-border spinner-border-sm" role="status"><\/span> Добавление...';try{const u=await fetch("/Catalog/AddToCart",{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body:"id="+encodeURIComponent(n)});if(!u.ok)throw new Error("HTTP "+u.status);const r=await u.json();if(!r.success)throw new Error(r.message||"Товар недоступен");const f=document.getElementById("cartBadge");f&&(f.textContent=r.cartCount);const e=document.getElementById("cartToast"),o=document.getElementById("cartToastText");e&&o&&window.bootstrap&&(o.textContent="Товар «"+r.productName+"» добавлен в корзину",bootstrap.Toast.getOrCreateInstance(e,{delay:3e3}).show());t.textContent="Добавлено ✓";t.classList.replace("btn-primary","btn-success");setTimeout(()=>{t.textContent=i,t.classList.replace("btn-success","btn-primary"),t.disabled=!1},2e3)}catch(r){console.error(r);t.textContent="Ошибка";setTimeout(()=>{t.textContent=i,t.disabled=!1},2e3)}}document.addEventListener("click",t=>{const i=t.target.closest(".add-to-cart");i&&!i.disabled&&n(i.dataset.productId,i)})})();